//! BL-QA-B1: accuracy of the Beta 1 conversion decision on a synthetic corpus.
//!
//! Data: `tests/data/corpus_beta1.tsv` (generated by `gen_corpus_beta1.py`; invented text only,
//! so printing it is allowed - it is not user data).
//!
//! Two sections (D-31): `corpus_beta1.tsv` is the caret mode (last word, `ConvertMode::Smart`);
//! `corpus_beta1_selection.tsv` (generated by `gen_corpus_beta1_selection.py` from the same
//! inputs) is the selection mode (`ConvertMode::Literal`, key for key, must pass completely).
//!
//! The caret decision mirrors `ks_engine::run_inner` (ks-core cannot depend on ks-engine):
//! detect -> a single language -> convert to the other one -> replace only when the confidence
//! is High and the text changed. In every other case the text in the field stays as it was.
//!
//! Failure kinds:
//! * `WRONG`   - the text was replaced with something other than the expected text
//!   (visible corruption of what the user typed);
//! * `FALSE`   - text that had to stay unchanged was replaced;
//! * `REFUSED` - text that had to be converted was left unchanged (harmless, but useless).
//!
//! The test prints the real numbers (run with `--nocapture`) and fails only when a category
//! drops below its floor. Floors are set just under the numbers measured on 065bc6d, so the
//! test is a regression guard, not an acceptance threshold: the defects it shows are tracked
//! in `docs/qa/beta1-qa-report.md`.

#![allow(
    clippy::print_stdout,
    reason = "the accuracy table is the purpose of this test; the corpus is synthetic"
)]

use ks_core::{Confidence, ConvertMode, Detection, builtin};
use std::collections::BTreeMap;

const CORPUS: &str = include_str!("data/corpus_beta1.tsv");
const SELECTION_CORPUS: &str = include_str!("data/corpus_beta1_selection.tsv");

/// Selection mode (D-31): a single-language selection is re-typed key for key; a mixed one
/// needs the language popup and is left as it is here.
#[test]
fn selection_corpus_is_literal() {
    let c = builtin().expect("built-in data");
    let mut cases = 0;
    let mut failures: Vec<String> = Vec::new();
    for line in SELECTION_CORPUS.lines() {
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let mut f = line.split('\t');
        let (Some(cat), Some(input), Some(expected), None) =
            (f.next(), f.next(), f.next(), f.next())
        else {
            panic!("malformed corpus line");
        };
        cases += 1;
        let actual = match c.detect(input) {
            Detection::Single(from) => {
                let to = c.languages().find(|l| *l != from).expect("two languages");
                let r = c
                    .convert_with(input, &from, to, ConvertMode::Literal)
                    .expect("convert");
                if r.confidence == Confidence::High {
                    r.text
                } else {
                    input.to_owned()
                }
            }
            Detection::Mixed(_) | Detection::NoLetters => input.to_owned(),
        };
        if actual != expected {
            failures.push(format!(
                "{cat:22} in={input:?} expected={expected:?} actual={actual:?}"
            ));
        }
    }
    println!(
        "\nD-31 selection corpus: {cases} cases, {} failures",
        failures.len()
    );
    for f in &failures {
        println!("  {f}");
    }
    assert!(cases >= 300, "selection corpus too small: {cases}");
    assert!(
        failures.is_empty(),
        "{} selection cases failed",
        failures.len()
    );
}

/// What ends up in the text field after one hotkey press, per the Beta 1 engine policy.
fn engine_result(c: &ks_core::Converter, input: &str) -> (String, &'static str) {
    let from = match c.detect(input) {
        Detection::NoLetters => return (input.to_owned(), "NO_LETTERS"),
        Detection::Mixed(_) => return (input.to_owned(), "MIXED"),
        Detection::Single(l) => l,
    };
    let Some(to) = c.languages().find(|l| *l != from).map(str::to_owned) else {
        return (input.to_owned(), "NO_TARGET");
    };
    match c.convert(input, &from, &to) {
        Ok(r) if r.confidence == Confidence::High => (r.text, "CONVERTED"),
        Ok(_) => (input.to_owned(), "LOW_CONFIDENCE"),
        Err(_) => (input.to_owned(), "ERROR"),
    }
}

#[derive(Default)]
struct Stat {
    total: usize,
    pass: usize,
    wrong: usize,
    false_conv: usize,
    refused: usize,
}

/// Minimum number of passing cases per category (measured numbers minus a small slack).
/// Categories not listed must pass completely.
fn floor(category: &str, total: usize) -> usize {
    let percent = match category {
        // FLOORS-BEGIN (kept in sync with docs/qa/beta1-qa-report.md)
        "mixed_lang_fix" => 0, // language popup is not in Beta 1: always refused
        // Raised after the QA-B1-01..03 fixes on feat/win-beta1 (was 23/28, 31/35, 36/38).
        "digits" => 95,           // measured 28/28
        "keep_tech" => 95,        // measured 35/35
        "punct_keys_en2ru" => 95, // measured 37/38 (`ytn?` -> `нет?`, expected `нет,`)
        _ => 100,
        // FLOORS-END
    };
    total * percent / 100
}

#[test]
fn corpus_accuracy_by_category() {
    let c = builtin().expect("built-in data");
    let mut stats: BTreeMap<&str, Stat> = BTreeMap::new();
    let mut failures: Vec<String> = Vec::new();
    let mut cases = 0;
    for line in CORPUS.lines() {
        if line.is_empty() || line.starts_with('#') {
            continue;
        }
        let mut f = line.split('\t');
        let (Some(cat), Some(input), Some(expected), None) =
            (f.next(), f.next(), f.next(), f.next())
        else {
            panic!("malformed corpus line");
        };
        cases += 1;
        let (actual, code) = engine_result(&c, input);
        let s = stats.entry(cat).or_default();
        s.total += 1;
        if actual == expected {
            s.pass += 1;
            continue;
        }
        let kind = if actual == input {
            s.refused += 1;
            "REFUSED"
        } else if input == expected {
            s.false_conv += 1;
            "FALSE"
        } else {
            s.wrong += 1;
            "WRONG"
        };
        failures.push(format!(
            "{kind:7} {cat:18} {code:14} in={input:?} expected={expected:?} actual={actual:?}"
        ));
    }
    assert!(cases >= 300, "corpus must have at least 300 cases: {cases}");

    println!("\nBL-QA-B1 corpus: {cases} cases");
    println!(
        "{:20} {:>5} {:>5} {:>6} {:>6} {:>6} {:>8}",
        "category", "total", "pass", "pass%", "WRONG", "FALSE", "REFUSED"
    );
    let mut all = Stat::default();
    let mut below: Vec<String> = Vec::new();
    for (cat, s) in &stats {
        println!(
            "{:20} {:>5} {:>5} {:>5.1}% {:>6} {:>6} {:>8}",
            cat,
            s.total,
            s.pass,
            100.0 * s.pass as f64 / s.total as f64,
            s.wrong,
            s.false_conv,
            s.refused
        );
        all.total += s.total;
        all.pass += s.pass;
        all.wrong += s.wrong;
        all.false_conv += s.false_conv;
        all.refused += s.refused;
        let min = floor(cat, s.total);
        if s.pass < min {
            below.push(format!("{cat}: {} passed, floor {min}", s.pass));
        }
    }
    println!(
        "{:20} {:>5} {:>5} {:>5.1}% {:>6} {:>6} {:>8}",
        "TOTAL",
        all.total,
        all.pass,
        100.0 * all.pass as f64 / all.total as f64,
        all.wrong,
        all.false_conv,
        all.refused
    );
    println!("\nfailures ({}):", failures.len());
    failures.sort();
    for f in &failures {
        println!("  {f}");
    }
    assert!(below.is_empty(), "categories below their floor: {below:?}");
}
